// Homologar acesso privado, credenciais e deploy da migration 033 antes de permitir processamento.
const ENABLED = false;
return ENABLED ? $input.all() : [];

const payload = $input.first()?.json;
if (!payload || payload.schema_version !== 1 || payload.send_enabled !== false ||
    !Array.isArray(payload.items) || payload.items.length > 10) {
  throw new Error("Lote de análise inválido.");
}
return payload.items.map((task) => {
  if (!task || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(task.claim_id) ||
      !Number.isSafeInteger(task.message_id) || task.message_id < 1 ||
      !["instagram", "waha"].includes(task.origin) ||
      typeof task.text !== "string" || !task.text.trim() || task.text.length > 8192 ||
      !Number.isInteger(task.attempt) || task.attempt < 1 || task.attempt > 3) {
    throw new Error("Item de análise inválido.");
  }
  return { json: { claim_id: task.claim_id, text: task.text }, pairedItem: { item: 0 } };
});

const task = $("Individualizar classificacoes").item.json;
const raw = $json.output;
if (typeof raw !== "string" || raw.length > 4096) {
  throw new Error("Classificação de IA inválida.");
}
let data;
try { data = JSON.parse(raw); } catch { throw new Error("A IA não retornou JSON estrito."); }
if (!data || typeof data !== "object" || Array.isArray(data) ||
    Object.keys(data).sort().join(",") !== "confidence,explanation,sentiment" ||
    !["positive", "negative", "neutral", "uncertain"].includes(data.sentiment) ||
    !["low", "medium", "high"].includes(data.confidence) ||
    typeof data.explanation !== "string") {
  throw new Error("Resultado fora do contrato de sentimento.");
}
const explanation = [...data.explanation.trim()].slice(0, 120).join("");
if (!explanation || /[\u0000-\u0008\u000B\u000C\u000E-\u001F]/.test(explanation)) {
  throw new Error("Explicação inválida.");
}
return { json: {
  claim_id: task.claim_id,
  sentiment: data.sentiment,
  confidence: data.confidence,
  explanation
} };
